'use client';

import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import { AlertTriangle, CheckCircle2, Loader2, Package, ShieldCheck } from 'lucide-react';
import type { ReactNode } from 'react';
import type { AuthChangeEvent, Session } from '@supabase/supabase-js';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { useCart } from '@/context/CartContext';
import {
  isTerminalConfirmationState,
  resolveConfirmationStateFromPublicStatus,
  shouldClearCartForApprovedOrder,
  type ConfirmationState,
} from '@/lib/checkout-confirmation';
import { getCheckoutConfirmationPrimaryHref } from '@/lib/frontend-routing';
import { apiFetch } from '@/utils/api';
import { createClient } from '@/utils/supabase/client';

export default function CheckoutConfirmationPage() {
  return (
    <Suspense fallback={<ConfirmationSkeleton />}>
      <CheckoutConfirmationContent />
    </Suspense>
  );
}

function CheckoutConfirmationContent() {
  const { t } = useTranslation();
  const { items, clearCart } = useCart();
  const searchParams = useSearchParams();
  const supabase = createClient();
  const orderId = searchParams.get('orderId');
  const [paymentState, setPaymentState] = useState<ConfirmationState>(
    orderId ? 'loading' : 'error',
  );
  const [orderStatus, setOrderStatus] = useState<string | null>(null);
  const [orderNumber, setOrderNumber] = useState<number | null>(null);
  const [hasSession, setHasSession] = useState(false);
  const successToastShownRef = useRef(false);

  useEffect(() => {
    let isActive = true;

    const syncSession = async () => {
      const {
        data: { session },
      } = await supabase.auth.getSession();

      if (!isActive) {
        return;
      }

      setHasSession(Boolean(session?.access_token));
    };

    void syncSession();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((
      _event: AuthChangeEvent,
      session: Session | null,
    ) => {
      if (!isActive) {
        return;
      }

      setHasSession(Boolean(session?.access_token));
    });

    return () => {
      isActive = false;
      subscription.unsubscribe();
    };
  }, [supabase.auth]);

  useEffect(() => {
    if (!orderId) {
      setPaymentState('error');
      return;
    }

    let isActive = true;
    let intervalId: number | null = null;

    const stopPolling = () => {
      if (intervalId !== null) {
        window.clearInterval(intervalId);
        intervalId = null;
      }
    };

    const syncOrderPaymentStatus = async () => {
      try {
        const response = await apiFetch(`/orders/public/${orderId}/payment-status`, {
          cache: 'no-store',
        });

        if (!response.ok) {
          throw new Error('No fue posible consultar el estado del pago.');
        }

        const result = await response.json();
        const data = result.data;

        if (!isActive) {
          return;
        }

        setOrderStatus(data.status);
        setOrderNumber(data.orderNumber);
        const nextState = resolveConfirmationStateFromPublicStatus(data);
        setPaymentState(nextState);

        if (isTerminalConfirmationState(nextState)) {
          stopPolling();
        }
      } catch (error) {
        console.error('Error checking payment confirmation:', error);
        if (isActive) {
          setPaymentState('error');
        }
        stopPolling();
      }
    };

    intervalId = window.setInterval(() => {
      void syncOrderPaymentStatus();
    }, 3000);
    void syncOrderPaymentStatus();

    return () => {
      isActive = false;
      stopPolling();
    };
  }, [orderId]);

  useEffect(() => {
    if (paymentState !== 'approved' || !orderId) {
      return;
    }

    if (shouldClearCartForApprovedOrder(orderId, items) && items.length > 0) {
      clearCart();
    }

    if (!successToastShownRef.current) {
      successToastShownRef.current = true;
      toast.success(t('checkout_payment_approved_toast'));
    }
  }, [clearCart, items, orderId, paymentState, t]);

  const heroCopy = useMemo(() => {
    switch (paymentState) {
      case 'approved':
        return {
          badge: t('checkout_confirmation_approved_badge'),
          title: t('checkout_confirmation_approved_title'),
          description: t('checkout_confirmation_approved_description'),
          iconClassName: 'bg-emerald-50 text-emerald-600',
          icon: <CheckCircle2 className="h-8 w-8" />,
        };
      case 'failed':
        return {
          badge: t('checkout_confirmation_failed_badge'),
          title: t('checkout_confirmation_failed_title'),
          description: t('checkout_confirmation_failed_description'),
          iconClassName: 'bg-amber-50 text-amber-600',
          icon: <AlertTriangle className="h-8 w-8" />,
        };
      case 'pending':
      case 'loading':
      case 'idle':
        return {
          badge: t('checkout_confirmation_pending_badge'),
          title: t('checkout_confirmation_pending_title'),
          description: t('checkout_confirmation_pending_description'),
          iconClassName: 'bg-sky-50 text-sky-600',
          icon:
            paymentState === 'loading' ? (
              <Loader2 className="h-8 w-8 animate-spin" />
            ) : (
              <ShieldCheck className="h-8 w-8" />
            ),
        };
      case 'error':
      default:
        return {
          badge: t('checkout_confirmation_error_badge'),
          title: t('checkout_confirmation_error_title'),
          description: t('checkout_confirmation_error_description'),
          iconClassName: 'bg-zinc-100 text-zinc-600',
          icon: <AlertTriangle className="h-8 w-8" />,
        };
    }
  }, [paymentState, t]);

  const infoCards = useMemo(() => {
    const referenceDescription = orderNumber
      ? t('checkout_confirmation_order_reference_number', {
          orderNumber,
          orderId: orderId ?? '',
        })
      : orderId
        ? t('checkout_confirmation_order_reference', { orderId })
        : t('checkout_confirmation_order_reference_fallback');

    const statusDescription = orderStatus
      ? t('checkout_confirmation_status_value', { status: orderStatus })
      : t('checkout_confirmation_status_loading');

    const nextStepDescription =
      paymentState === 'approved'
        ? t('checkout_confirmation_next_step_approved')
        : paymentState === 'failed'
          ? t('checkout_confirmation_next_step_failed')
          : t('checkout_confirmation_next_step_pending');

    return [
      {
        icon: <Package className="h-5 w-5" />,
        title: t('checkout_confirmation_card_order_title'),
        description: referenceDescription,
      },
      {
        icon: <ShieldCheck className="h-5 w-5" />,
        title: t('checkout_confirmation_card_status_title'),
        description: statusDescription,
      },
      {
        icon: <CheckCircle2 className="h-5 w-5" />,
        title: t('checkout_confirmation_card_next_title'),
        description: nextStepDescription,
      },
    ];
  }, [orderId, orderNumber, orderStatus, paymentState, t]);

  const primaryCtaHref = getCheckoutConfirmationPrimaryHref({
    hasSession,
    paymentState,
  });

  return (
    <main className="mx-auto flex min-h-[70vh] max-w-4xl flex-col justify-center gap-8 px-4 py-12 md:px-6">
      <section className="rounded-[2rem] border border-theme bg-surface p-8 shadow-sm md:p-10">
        <div className={`inline-flex rounded-2xl p-4 ${heroCopy.iconClassName}`}>
          {heroCopy.icon}
        </div>
        <div className="mt-6 space-y-3">
          <p className="text-[10px] font-black uppercase tracking-[0.22em] text-primary/70">
            {heroCopy.badge}
          </p>
          <h1 className="text-3xl font-black tracking-tight text-primary md:text-4xl">
            {heroCopy.title}
          </h1>
          <p className="max-w-2xl text-sm leading-7 text-muted">
            {heroCopy.description}
          </p>
        </div>

        {paymentState === 'approved' ? (
          <div className="mt-6 rounded-3xl border border-emerald-200 bg-emerald-50/80 p-5 text-sm leading-6 text-emerald-900">
            <p className="font-black uppercase tracking-[0.16em]">
              {t('checkout_confirmation_approved_notice_title')}
            </p>
            <p className="mt-2">{t('checkout_confirmation_approved_notice_body')}</p>
          </div>
        ) : null}

        <div className="mt-8 grid gap-4 md:grid-cols-3">
          {infoCards.map((card) => (
            <InfoCard
              key={card.title}
              icon={card.icon}
              title={card.title}
              description={card.description}
            />
          ))}
        </div>

        <div className="mt-8 flex flex-col gap-3 sm:flex-row">
          <Link
            href={primaryCtaHref}
            className="inline-flex items-center justify-center rounded-2xl bg-primary px-5 py-3 text-sm font-black uppercase tracking-[0.14em] text-base-color"
          >
            {paymentState === 'approved'
              ? t('checkout_confirmation_primary_cta_approved')
              : t('checkout_confirmation_primary_cta_default')}
          </Link>
          <Link
            href="/catalog"
            className="inline-flex items-center justify-center rounded-2xl border border-theme px-5 py-3 text-sm font-bold text-primary"
          >
            {t('checkout_confirmation_secondary_cta')}
          </Link>
        </div>
      </section>
    </main>
  );
}

function ConfirmationSkeleton() {
  return (
    <main className="mx-auto flex min-h-[70vh] max-w-4xl flex-col justify-center gap-8 px-4 py-12 md:px-6">
      <section className="rounded-[2rem] border border-theme bg-surface p-8 shadow-sm md:p-10">
        <div className="h-16 w-16 rounded-2xl bg-emerald-50" />
        <div className="mt-6 space-y-3">
          <div className="h-3 w-40 rounded bg-base/60" />
          <div className="h-10 w-72 rounded bg-base/60" />
          <div className="h-5 w-full max-w-2xl rounded bg-base/60" />
        </div>
      </section>
    </main>
  );
}

function InfoCard({
  icon,
  title,
  description,
}: {
  icon: ReactNode;
  title: string;
  description: string;
}) {
  return (
    <div className="rounded-3xl border border-theme bg-base/40 p-5">
      <div className="inline-flex rounded-2xl bg-primary/10 p-3 text-primary">{icon}</div>
      <h2 className="mt-4 text-lg font-black text-primary">{title}</h2>
      <p className="mt-2 text-sm leading-6 text-muted">{description}</p>
    </div>
  );
}
